// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    address actor = address(0xA11CE);

    function setUp() public {
        c = new MyContract();
        vm.prank(actor);
        c = new MyContract();
    }

    function testFuzz_property(uint256 amount, address receiver) public {
        vm.assume(receiver != address(0));
        vm.assume(receiver.code.length == 0);
        vm.assume(uint160(receiver) > 0x100);
        amount = bound(amount, 1, 2**64);
        vm.deal(address(c), amount + 1 ether);

        uint256 before = receiver.balance;
        vm.prank(actor);
        c.sendTo(receiver, amount);
        assertTrue(receiver.balance == before + amount);
    }
}
